-- 掲示板に最初から置いておくスレッド（管理人が立てた扱い）。公開のたびに実行されるが、同じタイトルのスレッドがあれば何もしない
-- （削除したスレッドも行は残るので、消したものが復活することはない）。足すときは同じ形で1件追加する。改行は char(10)。
-- ts・last は一覧の並び順（新しい順）を決めるための時刻。上に書いたものほど上に並ぶ。
-- 「はじめに」スレッドに付ける、書き方のお手本コメント（管理人の書き込み扱い。dev = 'seed'）。同じ本文がすでにあれば何もしない
INSERT OR IGNORE INTO bre (c, re) SELECT a.id, b.id FROM bcom a, bcom b WHERE a.dev = 'seed' AND a.body = '【デモ②返信】わかります。「返信」を押すと、このように相手の発言を引用して返せます。' AND b.dev = 'seed' AND b.body = '【デモ①ふつうのコメント】ライスの運動量が今季もすごい。守備でも攻撃でも顔を出してくれるので、見ていて頼もしいです。';
INSERT OR IGNORE INTO bre (c, re) SELECT a.id, b.id FROM bcom a, bcom b WHERE a.dev = 'seed' AND a.body = '【デモ③意見が違うとき】自分は少し違う見方で、今季はサカの調子が鍵だと思います。こういう形で理由を添えると会話が続きます。' AND b.dev = 'seed' AND b.body = '【デモ①ふつうのコメント】ライスの運動量が今季もすごい。守備でも攻撃でも顔を出してくれるので、見ていて頼もしいです。';
UPDATE bthread SET nc = (SELECT COUNT(*) FROM bcom WHERE t = bthread.id AND st = 0) WHERE title = 'はじめに：掲示板の使い方';
