INSERT INTO bthread (kind, tag, title, title_en, body, body_en, opts, close, late, pin, nocom, ts, last) SELECT 'talk', 'site', 'はじめに：掲示板の使い方', 'Welcome: how the board works', 'グーナー同士が気持ちよく語り合える、健全な掲示板を目指しています。ログインなしで、誰でも書き込み・投票・スレッド作成ができます。' || char(10) || '' || char(10) || '【できること】' || char(10) || '・コメントを書く（200文字まで）' || char(10) || '・特定の発言に「返信」で返す' || char(10) || '・アンケートに投票する' || char(10) || '・スレッドを立てる（1日5件まで）' || char(10) || '' || char(10) || '【お願い】' || char(10) || '・意見が違っても相手への敬意を忘れずに。批判はプレーや采配までにして、人を傷つける言葉は使わない' || char(10) || '・選手・監督・審判・相手チーム・ほかのファンへの誹謗中傷や差別は書かない' || char(10) || '・個人情報、宣伝、リンクは書かない' || char(10) || '・うわさは「〜と報じられている」と分かる形で' || char(10) || '・困った書き込みには言い返さず「通報」を。3人から通報があると自動で隠れます' || char(10) || '' || char(10) || '下のコメントは、書き方のお手本として管理人が書いたデモです。試し書きもここでどうぞ。', 'We want a friendly, healthy board where Gooners enjoy talking. No login needed.' || char(10) || '' || char(10) || '[What you can do]' || char(10) || '- Comment (up to 200 characters)' || char(10) || '- "Reply" to a specific comment' || char(10) || '- Vote in polls' || char(10) || '- Start a thread (up to 5 a day)' || char(10) || '' || char(10) || '[House rules]' || char(10) || '- Disagree with respect. Criticise performances and decisions, not people' || char(10) || '- No abuse or discrimination toward players, referees or other fans' || char(10) || '- No personal information, ads or links' || char(10) || '- Make it clear when something is a rumour' || char(10) || '- Do not argue with bad posts: tap "Report"' || char(10) || '' || char(10) || 'The comments below are demo posts by the admin. Feel free to test-post here.', NULL, NULL, 0, 1, 0, (CAST(strftime('%s','now') AS INTEGER) * 1000 - 0), (CAST(strftime('%s','now') AS INTEGER) * 1000 - 0) WHERE NOT EXISTS (SELECT 1 FROM bthread WHERE title = 'はじめに：掲示板の使い方');
INSERT INTO bthread (kind, tag, title, title_en, body, body_en, opts, close, late, pin, nocom, ts, last) SELECT 'talk', 'match', '【試合スレ】マンチェスター・シティ戦（プレミアリーグ・11/30 1:30キックオフ）', 'Match thread: Manchester City (Premier League, home)', 'ホームでのシティ戦。スタメン予想、試合中の実況、試合後の感想までここでどうぞ。', 'City at home. Predicted line-ups, live reactions and post-match thoughts all go here.', NULL, NULL, 0, 0, 0, (CAST(strftime('%s','now') AS INTEGER) * 1000 - 1000), (CAST(strftime('%s','now') AS INTEGER) * 1000 - 1000) WHERE NOT EXISTS (SELECT 1 FROM bthread WHERE title = '【試合スレ】マンチェスター・シティ戦（プレミアリーグ・11/30 1:30キックオフ）');
INSERT INTO bthread (kind, tag, title, title_en, body, body_en, opts, close, late, pin, nocom, ts, last) SELECT 'poll', 'transfer', '冬の移籍市場、いちばん補強してほしいポジションは？', 'Which position should Arsenal strengthen in January?', '1月の移籍市場が近づいてきました。理由や候補の選手もコメントで教えてください。', 'The January window is getting close. Tell us why, and who, in the comments.', '[{"ja": "ゴールキーパー", "en": "Goalkeeper"}, {"ja": "センターバック", "en": "Centre-back"}, {"ja": "サイドバック", "en": "Full-back"}, {"ja": "中盤", "en": "Midfield"}, {"ja": "ウイング", "en": "Winger"}, {"ja": "センターフォワード", "en": "Centre-forward"}, {"ja": "補強はいらない", "en": "No signings needed"}]', 1798729140000, 0, 0, 0, (CAST(strftime('%s','now') AS INTEGER) * 1000 - 2000), (CAST(strftime('%s','now') AS INTEGER) * 1000 - 2000) WHERE NOT EXISTS (SELECT 1 FROM bthread WHERE title = '冬の移籍市場、いちばん補強してほしいポジションは？');
INSERT INTO bthread (kind, tag, title, title_en, body, body_en, opts, close, late, pin, nocom, ts, last) SELECT 'poll', 'talk', '今季ここまでのMVPは誰？', 'Who is Arsenal’s player of the season so far?', '選択肢にない選手は「ほかの選手」に入れて、コメントで名前を教えてください。', 'If your pick is not listed, choose "Someone else" and name them in the comments.', '[{"ja": "ブカヨ・サカ", "en": "Bukayo Saka"}, {"ja": "デクラン・ライス", "en": "Declan Rice"}, {"ja": "ダビド・ラヤ", "en": "David Raya"}, {"ja": "マルティン・ウーデゴール", "en": "Martin Ødegaard"}, {"ja": "ヴィクトル・ギェケレシュ", "en": "Viktor Gyökeres"}, {"ja": "ウィリアム・サリバ", "en": "William Saliba"}, {"ja": "ガブリエウ・マガリャンイス", "en": "Gabriel Magalhães"}, {"ja": "ほかの選手", "en": "Someone else"}]', NULL, 0, 0, 0, (CAST(strftime('%s','now') AS INTEGER) * 1000 - 3000), (CAST(strftime('%s','now') AS INTEGER) * 1000 - 3000) WHERE NOT EXISTS (SELECT 1 FROM bthread WHERE title = '今季ここまでのMVPは誰？');
INSERT INTO bthread (kind, tag, title, title_en, body, body_en, opts, close, late, pin, nocom, ts, last) SELECT 'talk', 'talk', '自己紹介・グーナー歴を語ろう', 'Introduce yourself: how did you become a Gooner?', 'いつから、何がきっかけでアーセナルを応援していますか？ 好きな選手や思い出の試合もぜひ。', 'When and why did you start supporting Arsenal? Favourite players and matches welcome.', NULL, NULL, 0, 0, 0, (CAST(strftime('%s','now') AS INTEGER) * 1000 - 4000), (CAST(strftime('%s','now') AS INTEGER) * 1000 - 4000) WHERE NOT EXISTS (SELECT 1 FROM bthread WHERE title = '自己紹介・グーナー歴を語ろう');
INSERT INTO bthread (kind, tag, title, title_en, body, body_en, opts, close, late, pin, nocom, ts, last) SELECT 'talk', 'site', 'サイトへの要望・ほしい機能', 'Site requests & feature ideas', 'このサイトにほしい機能や、使いにくいところを教えてください。立ててほしいスレッドの案も歓迎です。', 'Tell us what you would like to see on this site, or what is hard to use. Thread ideas are welcome too.', NULL, NULL, 0, 0, 0, (CAST(strftime('%s','now') AS INTEGER) * 1000 - 5000), (CAST(strftime('%s','now') AS INTEGER) * 1000 - 5000) WHERE NOT EXISTS (SELECT 1 FROM bthread WHERE title = 'サイトへの要望・ほしい機能');
INSERT INTO bcom (t, dev, iph, name, body, st, adm, why, ts) SELECT (SELECT id FROM bthread WHERE title = 'はじめに：掲示板の使い方'), 'seed', NULL, '管理人', '【デモ①ふつうのコメント】ライスの運動量が今季もすごい。守備でも攻撃でも顔を出してくれるので、見ていて頼もしいです。', 0, 1, NULL, (CAST(strftime('%s','now') AS INTEGER) * 1000 + 0) WHERE EXISTS (SELECT 1 FROM bthread WHERE title = 'はじめに：掲示板の使い方') AND NOT EXISTS (SELECT 1 FROM bcom WHERE dev = 'seed' AND body = '【デモ①ふつうのコメント】ライスの運動量が今季もすごい。守備でも攻撃でも顔を出してくれるので、見ていて頼もしいです。');
INSERT INTO bcom (t, dev, iph, name, body, st, adm, why, ts) SELECT (SELECT id FROM bthread WHERE title = 'はじめに：掲示板の使い方'), 'seed', NULL, '管理人', '【デモ②返信】わかります。「返信」を押すと、このように相手の発言を引用して返せます。', 0, 1, NULL, (CAST(strftime('%s','now') AS INTEGER) * 1000 + 1000) WHERE EXISTS (SELECT 1 FROM bthread WHERE title = 'はじめに：掲示板の使い方') AND NOT EXISTS (SELECT 1 FROM bcom WHERE dev = 'seed' AND body = '【デモ②返信】わかります。「返信」を押すと、このように相手の発言を引用して返せます。');
INSERT INTO bcom (t, dev, iph, name, body, st, adm, why, ts) SELECT (SELECT id FROM bthread WHERE title = 'はじめに：掲示板の使い方'), 'seed', NULL, '管理人', '【デモ③意見が違うとき】自分は少し違う見方で、今季はサカの調子が鍵だと思います。こういう形で理由を添えると会話が続きます。', 0, 1, NULL, (CAST(strftime('%s','now') AS INTEGER) * 1000 + 2000) WHERE EXISTS (SELECT 1 FROM bthread WHERE title = 'はじめに：掲示板の使い方') AND NOT EXISTS (SELECT 1 FROM bcom WHERE dev = 'seed' AND body = '【デモ③意見が違うとき】自分は少し違う見方で、今季はサカの調子が鍵だと思います。こういう形で理由を添えると会話が続きます。');
INSERT INTO bcom (t, dev, iph, name, body, st, adm, why, ts) SELECT (SELECT id FROM bthread WHERE title = 'はじめに：掲示板の使い方'), 'seed', NULL, '管理人', '【デモ④うわさの話】〇〇の獲得に動いていると現地で報じられているそうです。まだ確定ではないので続報を待ちたいですね。', 0, 1, NULL, (CAST(strftime('%s','now') AS INTEGER) * 1000 + 3000) WHERE EXISTS (SELECT 1 FROM bthread WHERE title = 'はじめに：掲示板の使い方') AND NOT EXISTS (SELECT 1 FROM bcom WHERE dev = 'seed' AND body = '【デモ④うわさの話】〇〇の獲得に動いていると現地で報じられているそうです。まだ確定ではないので続報を待ちたいですね。');
INSERT INTO bcom (t, dev, iph, name, body, st, adm, why, ts) SELECT (SELECT id FROM bthread WHERE title = 'はじめに：掲示板の使い方'), 'seed', NULL, '管理人', '【デモ⑤困った書き込みを見たら】言い返さずに、そのコメントの「通報」を押してください。それでは、楽しく語り合いましょう！ COYG', 0, 1, NULL, (CAST(strftime('%s','now') AS INTEGER) * 1000 + 4000) WHERE EXISTS (SELECT 1 FROM bthread WHERE title = 'はじめに：掲示板の使い方') AND NOT EXISTS (SELECT 1 FROM bcom WHERE dev = 'seed' AND body = '【デモ⑤困った書き込みを見たら】言い返さずに、そのコメントの「通報」を押してください。それでは、楽しく語り合いましょう！ COYG');
